jsonTools.init:
function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var KEY_PREFIX = "_rn_narr_";   // bounded buffer per CLAUDE.md
  var MAX_CACHED = 5;

  // ── Cache (per docHash) ────────────────────────────────────────────
  function _save(docHash, payload) {
    var row = { key: KEY_PREFIX + docHash, payload: payload, savedAt: Date.now() };
    try {
      return eli.storage.put(STORE, row).then(function () { _prune(); }).catch(function () {});
    } catch (_e) { return Promise.resolve(); }
  }
  function _load(docHash) {
    try {
      return eli.storage.get(STORE, KEY_PREFIX + docHash)
        .then(function (r) { return r ? r.payload : null; })
        .catch(function () { return null; });
    } catch (_e) { return Promise.resolve(null); }
  }
  function _prune() {
    try {
      return eli.storage.getAll(STORE).then(function (all) {
        if (!Array.isArray(all)) return;
        var mine = all.filter(function (r) {
          return r && typeof r.key === "string" && r.key.indexOf(KEY_PREFIX) === 0;
        });
        mine.sort(function (a, b) { return (b.savedAt || 0) - (a.savedAt || 0); });
        var excess = mine.slice(MAX_CACHED);
        return Promise.all(excess.map(function (r) {
          return eli.storage.delete(STORE, r.key).catch(function () {});
        }));
      }).catch(function () {});
    } catch (_e) { return Promise.resolve(); }
  }

  // ── Cheap djb2 hash for cache keys ────────────────────────────────
  function _hash(s) {
    var h = 5381, str = String(s || "");
    for (var i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
    return (h >>> 0).toString(36);
  }

  // ── Read tracked changes + surrounding context ─────────────────────
  // Pulls each TrackedChange's text + a 100-char context window from body
  // text. Context is what makes the AI's grouping useful — a bare
  // "60 days" → "90 days" diff is meaningless without "notice period".
  function _readChanges() {
    return eli.host.runRaw("redline_narrator:read", function (ctx) {
      var body = ctx.document.body;
      body.load("text");
      var tcs = body.getTrackedChanges();
      tcs.load("items");
      return ctx.sync().then(function () {
        var items = tcs.items || [];
        items.forEach(function (tc) { tc.load("text,author,type"); });
        return ctx.sync().then(function () {
          var bodyText = body.text || "";
          var changes = items.map(function (tc) {
            var t = String(tc.text || "").trim();
            var contextStr = "";
            if (t) {
              var pos = bodyText.indexOf(t);
              if (pos !== -1) {
                var s = Math.max(0, pos - 100);
                var e = Math.min(bodyText.length, pos + t.length + 100);
                contextStr = bodyText.substring(s, e).replace(/\s+/g, " ").trim();
              }
            }
            return {
              type: String(tc.type || "unknown").toLowerCase(),
              author: String(tc.author || "").trim() || null,
              text: t,
              context: contextStr,
            };
          }).filter(function (c) { return c.text.length > 0; });
          return { bodyText: bodyText, changes: changes };
        });
      });
    });
  }

  // ── Build AI prompt ───────────────────────────────────────────────
  function _buildPrompt(changes) {
    var changesBlock = changes.map(function (c, i) {
      var tag = c.type === "deletion" ? "DELETED" : c.type === "insertion" ? "INSERTED" : "MODIFIED";
      var line = "Change #" + (i + 1) + " [" + tag + "]: \"" + c.text + "\"";
      if (c.context) line += "\n  Context: \"…" + c.context + "…\"";
      return line;
    }).join("\n\n");
    return [
      "You are writing a plain-English changelog of tracked changes in a legal contract.",
      "Audience: a busy lawyer who wants the gist in 15 seconds.",
      "",
      "TOTAL CHANGES: " + changes.length,
      "",
      "INPUT — every tracked change with surrounding context:",
      changesBlock,
      "",
      "OUTPUT — JSON matching the schema:",
      "  • headline: ONE sentence, MAX 18 words, active voice, concrete verbs",
      "  • themes: 3–5 thematic groupings. For each:",
      "      - icon: a single emoji that fits the theme (🛡 risk, 💰 money, 🔒 IP,",
      "        ⏱ time, 📋 process, 🤝 relationship, 📦 deliverables, etc.)",
      "      - title: 2–3 word theme name",
      "      - bullets: 1–4 sentences, each describing a substantive change",
      "",
      "RULES (strict):",
      "  • SKIP non-substantive changes entirely: typos, capitalization, punctuation,",
      "    formatting, whitespace, re-ordering, definitional reshuffles.",
      "    Do NOT mention them — they shouldn't appear anywhere in the output.",
      "  • Active voice. Concrete verbs: \"narrowed\", \"added\", \"shifted\",",
      "    \"deleted\", \"expanded\", \"capped\", \"removed\", \"introduced\".",
      "  • No legalese, no \"the parties agree\", no \"thereunder\", no",
      "    \"with respect to\". Talk like a partner briefing an associate.",
      "  • Cite section numbers when visible in context (e.g., \"(Sec. 7.1)\").",
      "  • If a change's meaning isn't clear from context, do NOT invent one.",
      "    Either skip it or describe it as \"clarified language in [topic]\".",
      "  • If ALL changes are non-substantive, return an empty themes array and",
      "    headline: \"Only stylistic changes — no substantive edits.\"",
      "",
      "Return ONLY the JSON.",
    ].join("\n");
  }

  // ── AI call ───────────────────────────────────────────────────────
  function _generate(changes) {
    var schema = {
      type: "object",
      properties: {
        headline: { type: "string" },
        themes: {
          type: "array",
          items: {
            type: "object",
            properties: {
              icon: { type: "string" },
              title: { type: "string" },
              bullets: { type: "array", items: { type: "string" } },
            },
          },
        },
      },
      required: ["headline", "themes"],
    };
    return eli.ai.completeJSON(_buildPrompt(changes), schema, { sanitize: false });
  }

  // ── Rendering ─────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _goBack() {
    try { eli.fsm.transition("idle"); } catch (_e) {}
    if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
  }

  function _renderHeader(mount, changeCount) {
    return '<div class="_rn_header">' +
      '<button class="_rn_back" type="button" title="Back">←</button>' +
      '<div class="_rn_header_main">' +
        '<div class="_rn_header_eyebrow">BETA · ADMIN</div>' +
        '<div class="_rn_header_title">📰 Redline Narrator</div>' +
      '</div>' +
      (changeCount != null
        ? '<div class="_rn_header_count">' + changeCount + ' change' + (changeCount === 1 ? "" : "s") + '</div>'
        : '') +
    '</div>';
  }

  function _renderLoading(mount, msg) {
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, null) +
        '<div class="_rn_loading">' +
          '<div class="_rn_spinner"></div>' +
          '<div class="_rn_loading_text">' + _esc(msg) + '</div>' +
        '</div>' +
      '</div>';
    var b = mount.querySelector("._rn_back");
    if (b) b.onclick = _goBack;
  }

  function _renderEmpty(mount) {
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, 0) +
        '<div class="_rn_empty">' +
          '<div class="_rn_empty_icon">📭</div>' +
          '<div class="_rn_empty_title">No tracked changes</div>' +
          '<div class="_rn_empty_desc">Open a redlined draft and run Redline Narrator again to get a plain-English summary.</div>' +
        '</div>' +
      '</div>';
    mount.querySelector("._rn_back").onclick = _goBack;
  }

  function _renderError(mount, err) {
    var msg = (err && err.message) || "Unknown error";
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, null) +
        '<div class="_rn_empty">' +
          '<div class="_rn_empty_icon">⚠️</div>' +
          '<div class="_rn_empty_title">Couldn\'t generate summary</div>' +
          '<div class="_rn_empty_desc">' + _esc(msg) + '</div>' +
          '<button class="_rn_btn _rn_btn_retry" type="button" style="margin-top:14px;">Try again</button>' +
        '</div>' +
      '</div>';
    mount.querySelector("._rn_back").onclick = _goBack;
    mount.querySelector("._rn_btn_retry").onclick = function () { _show(); };
  }

  function _renderResult(mount, result, fromCache, changeCount) {
    var html =
      '<div class="_rn_root">' +
        _renderHeader(mount, changeCount) +
        '<div class="_rn_body">' +
          '<div class="_rn_summary_card">' +
            '<div class="_rn_summary_eyebrow">✦ Plain-English Summary</div>' +
            '<div class="_rn_summary_headline">' + _esc(result.headline || "(no headline)") + '</div>' +
          '</div>';

    var themes = Array.isArray(result.themes) ? result.themes : [];
    if (!themes.length) {
      html += '<div class="_rn_only_stylistic">No substantive edits detected. All tracked changes appear to be stylistic or formatting-only.</div>';
    } else {
      themes.forEach(function (theme) {
        var icon = String((theme && theme.icon) || "•").trim() || "•";
        var title = String((theme && theme.title) || "").trim();
        var bullets = Array.isArray(theme.bullets) ? theme.bullets : [];
        html += '<div class="_rn_theme">' +
          '<div class="_rn_theme_head">' +
            '<span class="_rn_theme_icon">' + _esc(icon) + '</span>' +
            '<span class="_rn_theme_title">' + _esc(title) + '</span>' +
          '</div>' +
          '<ul class="_rn_theme_list">';
        bullets.forEach(function (b) {
          html += '<li>' + _esc(b) + '</li>';
        });
        html += '</ul></div>';
      });
    }

    html +=
        '<div class="_rn_actions">' +
          '<button class="_rn_btn _rn_btn_copy" type="button">📋 Copy summary</button>' +
          '<button class="_rn_btn _rn_btn_regen" type="button">🔄 Regenerate</button>' +
        '</div>' +
        (fromCache
          ? '<div class="_rn_cache_note">↩ Loaded from cache — click Regenerate for a fresh take.</div>'
          : '') +
      '</div></div>';

    mount.innerHTML = html;
    mount.querySelector("._rn_back").onclick = _goBack;
    mount.querySelector("._rn_btn_copy").onclick = function () {
      var txt = _resultToText(result, changeCount);
      try {
        navigator.clipboard.writeText(txt).then(function () {
          if (typeof showToast === "function") showToast("Copied to clipboard", "ok");
        }).catch(function () {
          if (typeof showToast === "function") showToast("Copy failed", "err");
        });
      } catch (_e) {
        if (typeof showToast === "function") showToast("Copy not available", "warn");
      }
    };
    mount.querySelector("._rn_btn_regen").onclick = function () {
      // Force a fresh AI call by clearing the cache for this doc and re-running.
      _show({ forceRegen: true });
    };
  }

  function _resultToText(result, count) {
    var lines = [];
    lines.push("Redline Narrator — " + count + " tracked change" + (count === 1 ? "" : "s"));
    lines.push("");
    lines.push(result.headline || "");
    lines.push("");
    (result.themes || []).forEach(function (t) {
      lines.push((t.icon || "•") + " " + (t.title || ""));
      (t.bullets || []).forEach(function (b) { lines.push("  • " + b); });
      lines.push("");
    });
    return lines.join("\n").trim();
  }

  // ── Main entry ────────────────────────────────────────────────────
  function _show(opts) {
    opts = opts || {};
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    try { eli.fsm.transition("rendering"); } catch (_e) {}
    _renderLoading(mount, "Reading tracked changes…");

    _readChanges().then(function (doc) {
      if (!doc || !doc.changes || !doc.changes.length) {
        _renderEmpty(mount);
        return;
      }
      var fp = doc.changes.map(function (c) { return c.type + "|" + c.text; }).join("##");
      var docHash = _hash((doc.bodyText || "").slice(0, 5000) + "::" + fp);
      var maybeCache = opts.forceRegen ? Promise.resolve(null) : _load(docHash);
      return maybeCache.then(function (cached) {
        if (cached) {
          _renderResult(mount, cached, true, doc.changes.length);
          return;
        }
        _renderLoading(mount, "Synthesizing summary…");
        return _generate(doc.changes).then(function (result) {
          _save(docHash, result);
          _renderResult(mount, result, false, doc.changes.length);
        });
      });
    }).catch(function (err) {
      _renderError(mount, err);
    });
  }

  eli.register({
    tile: { app_redline_narrator: _show },
  });

  eli.log.event("tool", "redline_narrator_initialized", {});
}

jsonTools.css:
/* Redline Narrator — premium light surface, gold accents, themed bullet
   cards. Same design language as Build Draft / Agreement at a Glance. */

._rn_root {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: #f8fafc;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #0f172a;
}
/* Override the dark dashboard root background — same `:has()` trick the
   other light tools use to make this view feel like a standalone surface. */
#_eli3_dashboard_root:has(._rn_root) { background: #f8fafc; }

/* ── Header bar ─────────────────────────────────────────────────── */
._rn_header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
  border-bottom: 3px solid #c9a227;
  box-shadow: 0 2px 0 rgba(201,162,39,0.12), 0 4px 8px rgba(15,23,42,0.06);
}
._rn_back {
  flex: 0 0 auto;
  width: 30px; height: 30px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  color: #f8fafc;
  font-size: 16px;
  border-radius: 8px;
  cursor: pointer;
  transition: background .15s, transform .12s;
}
._rn_back:hover { background: rgba(255,255,255,0.16); }
._rn_back:active { transform: scale(0.95); }

._rn_header_main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
._rn_header_eyebrow {
  font-size: 9px; font-weight: 800; letter-spacing: 0.22em;
  text-transform: uppercase; color: #c9a227;
}
._rn_header_title { font-size: 16px; font-weight: 800; letter-spacing: 0.1px; }

._rn_header_count {
  flex: 0 0 auto;
  padding: 4px 10px;
  background: rgba(201,162,39,0.18);
  color: #fef3c7;
  border: 1px solid rgba(201,162,39,0.45);
  font-size: 11px; font-weight: 700; letter-spacing: 0.04em;
  border-radius: 0;
}

/* ── Body ───────────────────────────────────────────────────────── */
._rn_body {
  flex: 1; overflow-y: auto;
  padding: 20px 18px;
  display: flex; flex-direction: column; gap: 14px;
}

/* ── Hero summary card ──────────────────────────────────────────── */
._rn_summary_card {
  padding: 22px 24px;
  background: linear-gradient(180deg, #fffdf6 0%, #fef9e7 100%);
  border: 1px solid #c9a227;
  border-left: 4px solid #b8860b;
  border-radius: 12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 1px 2px rgba(184,134,11,0.06),
    0 8px 20px -4px rgba(184,134,11,0.18);
}
._rn_summary_eyebrow {
  font-size: 10px; font-weight: 900; letter-spacing: 0.24em;
  text-transform: uppercase; color: #7c2d12;
  margin-bottom: 8px;
}
._rn_summary_headline {
  font: 800 18px/1.4 'Georgia', 'Times New Roman', serif;
  color: #1a1407;
  letter-spacing: -0.1px;
}

/* ── Theme cards ────────────────────────────────────────────────── */
._rn_theme {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #94a3b8;
  border-radius: 10px;
  padding: 14px 16px 12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.85),
    0 1px 2px rgba(15,23,42,0.04),
    0 4px 12px -4px rgba(15,23,42,0.06);
}
._rn_theme_head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 1px dashed #cbd5e1;
}
._rn_theme_icon {
  font-size: 18px; line-height: 1;
  filter: drop-shadow(0 1px 2px rgba(15,23,42,0.08));
}
._rn_theme_title {
  font-size: 11px; font-weight: 900; letter-spacing: 0.14em;
  text-transform: uppercase; color: #0f172a;
}
._rn_theme_list {
  list-style: none;
  margin: 0; padding: 0;
  display: flex; flex-direction: column; gap: 6px;
}
._rn_theme_list li {
  position: relative;
  padding-left: 18px;
  font-size: 12.5px; line-height: 1.5; color: #334155;
}
._rn_theme_list li::before {
  content: "▸";
  position: absolute;
  left: 4px; top: 0;
  color: #c9a227;
  font-size: 12px;
}

._rn_only_stylistic {
  padding: 14px 16px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #94a3b8;
  font-size: 12px; color: #475569; font-style: italic;
  border-radius: 8px;
}

/* ── Action buttons ─────────────────────────────────────────────── */
._rn_actions {
  display: flex; gap: 10px; flex-wrap: wrap;
  margin-top: 8px;
}
._rn_btn {
  flex: 1 1 auto;
  padding: 10px 16px;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #334155;
  font: 700 11.5px/1 'Inter', sans-serif;
  letter-spacing: 0.04em;
  cursor: pointer;
  border-radius: 8px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 1px 2px rgba(15,23,42,0.05),
    0 4px 10px -4px rgba(15,23,42,0.08);
  transition: all .15s ease;
}
._rn_btn:hover {
  background: linear-gradient(180deg, #fffef9 0%, #fef9e7 100%);
  border-color: #d4b948;
  color: #7c4a03;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.95),
    0 1px 2px rgba(184,134,11,0.08),
    0 6px 14px -4px rgba(184,134,11,0.18);
  transform: translateY(-1px);
}
._rn_btn:active { transform: translateY(0); }
._rn_btn_copy { flex: 2 1 0; }   /* primary action a bit wider */

._rn_cache_note {
  margin-top: 6px;
  font-size: 10.5px; color: #94a3b8;
  text-align: center; font-style: italic;
}

/* ── Loading state ──────────────────────────────────────────────── */
._rn_loading {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 18px;
  padding: 60px 20px;
}
._rn_spinner {
  width: 40px; height: 40px;
  border: 3px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _rn_spin 0.8s linear infinite;
}
@keyframes _rn_spin { to { transform: rotate(360deg); } }
._rn_loading_text {
  font-size: 13px; font-weight: 600; color: #475569;
}

/* ── Empty / error states ───────────────────────────────────────── */
._rn_empty {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 12px; padding: 60px 28px;
  text-align: center;
}
._rn_empty_icon { font-size: 48px; line-height: 1; opacity: 0.55; }
._rn_empty_title { font-size: 18px; font-weight: 800; color: #0f172a; letter-spacing: -0.2px; }
._rn_empty_desc { font-size: 12.5px; line-height: 1.5; color: #64748b; max-width: 360px; }
